/*
 * [演算法說明]
 * 這是一個最大二分圖匹配 (Maximum Bipartite Matching) 問題。
 * 
 * 演算法步驟：
 * 1. 建立兩組節點：地鼠 (Gophers) 和 洞穴 (Holes)。
 * 2. 如果地鼠能在 s 秒內以速度 v 到達某個洞穴（距離 <= s * v），則在地鼠與該洞穴之間連一條邊。
 * 3. 使用匈牙利演算法 (Hungarian Algorithm) 或最大流演算法求出最大匹配數，即最多有多少隻地鼠能進洞。
 * 4. 脆弱的地鼠數 = 總地鼠數 - 最大匹配數。
 */

#include <iostream>
#include <vector>
#include <cmath>
#include <iomanip>

using namespace std;

struct Point {
    double x, y;
};

vector<int> match;
vector<bool> vis;
vector<vector<int>> adj;

bool dfs(int u) {
    for (int v : adj[u]) {
        if (!vis[v]) {
            vis[v] = true;
            if (match[v] < 0 || dfs(match[v])) {
                match[v] = u;
                return true;
            }
        }
    }
    return false;
}

int main() {
    int n, m, s, v;
    while (cin >> n >> m >> s >> v) {
        vector<Point> gophers(n), holes(m);
        for (int i = 0; i < n; ++i) cin >> gophers[i].x >> gophers[i].y;
        for (int i = 0; i < m; ++i) cin >> holes[i].x >> holes[i].y;

        adj.assign(n, vector<int>());
        double max_dist = (double)s * v;
        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < m; ++j) {
                double dist = sqrt(pow(gophers[i].x - holes[j].x, 2) + pow(gophers[i].y - holes[j].y, 2));
                if (dist <= max_dist) {
                    adj[i].push_back(j);
                }
            }
        }

        int result = 0;
        match.assign(m, -1);
        for (int i = 0; i < n; ++i) {
            vis.assign(m, false);
            if (dfs(i)) result++;
        }
        cout << n - result << endl;
    }
    return 0;
}
